    "text": "Analiza teritorială arată că strategia forestieră regională tratează tema „Bilanțul de carbon al sectorului LULUCF forestier” ca pe o componentă structurală a planificării teritoriale, distinctă de analiza punctuală a unui amplasament și ancorată la scara întregii regiuni forestiere. Abordarea integrează diagnoza fondului forestier, proiecția pe orizontul 2030 și 2050, precum și mecanismele de guvernanță prevăzute de Codul silvic (Legea 46/2008) și de Strategia Forestieră Națională. Cadrul european este dat de Strategia UE pentru Păduri 2030 și de Regulamentul (UE) 2023/1115 (EUDR), iar sursele cantitative provin din Romsilva, INCDS „Marin Drăcea”, EEA, Copernicus, EFFIS, FAO FRA 2020, Eurostat, Garda Forestieră și IGF (Inventarul Forestier Național). Obiectivul capitolului este de a stabili o bază comună de date și de a corela măsurile cu rețeaua de coridoare ecologice și de arii protejate la nivelul întregii regiuni forestiere analizate, evitând suprapunerea cu studiul punctual al unui amplasament."
